import sys, json
data = json.load(sys.stdin)
# Fix the key from missing-key to password
for container in data['spec']['template']['spec']['containers']:
    for env in container.get('env', []):
        if 'valueFrom' in env and 'secretKeyRef' in env['valueFrom']:
            env['valueFrom']['secretKeyRef']['key'] = 'password'
print(json.dumps(data, indent=2))
" > /tmp/fix-deployment.json && kubectl apply -f /tmp/fix-deployment.json -n default"}

{"command":"kubectl get pods -n default -o json | python3 -c "
import sys, json
data = json.load(sys.stdin)
for pod in data['items']:
    name = pod['metadata']['name']
    status = pod['status']['phase']
    # Get secret key from containers
    for container in pod.get('spec', {}).get('containers', []):
        if 'env' in container:
            for env in container['env']:
                if 'valueFrom' in env and 'secretKeyRef' in env['valueFrom']:
                    key = env['valueFrom']['secretKeyRef'].get('key', 'N/A')
                    print(f\"{name}: {status}, using key '{key}'\")
    if not any('env' in c for c in pod.get('spec', {}).get('containers', [])):
        print(f\"{name}: {status} (no env)\")
""}

